const bgVideo = document.querySelector('video[src="videos/SAMUDRA.webm"]');

if (bgVideo) {
  bgVideo.muted = false; 
  bgVideo.play().catch(() => {});

  // Tambahkan teks di bawah tengah layar
  const infoText = document.createElement('div');
  infoText.innerText = 'Tekan [SPASI] untuk Play/Pause Musik';
  infoText.style.position = 'fixed';
  infoText.style.bottom = '30px';
  infoText.style.left = '50%';
  infoText.style.transform = 'translateX(-50%)';
  infoText.style.color = 'white';
  infoText.style.fontFamily = 'Arial, sans-serif';
  infoText.style.fontSize = '18px';
  infoText.style.textShadow = '0 0 10px rgba(0, 64, 255, 0.52)';
  infoText.style.pointerEvents = 'none';
  document.body.appendChild(infoText);

  // Toggle suara video saat spasi ditekan
  document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') {
      e.preventDefault();
      bgVideo.muted = !bgVideo.muted; // mute/unmute suara
    }
  });
}

